// Validate factory webhook input + derive command identity
//
// Command detection trigger: paired action sequence (A always followed by B)
// → user has memorized a multi-step procedure → candidate for slash command.
//
// Pattern shape: { actions: ['acquire_lock', 'fetch_state', 'commit'], occurrence_count, ... }

const body = $input.first().json.body || $input.first().json;
const pattern = body.pattern;

if (!pattern || (!pattern.action && !pattern.actions)) {
  throw new Error('pattern.action or pattern.actions required');
}

const primaryAction = pattern.actions ? pattern.actions[0] : pattern.action;

// Derive command from primary action
const slug = String(primaryAction)
  .toLowerCase()
  .replace(/^aisha[_-]/, '')
  .replace(/_/g, '-')
  .replace(/[^a-z0-9-]/g, '');

const commandName = `aisha-${slug}`;
const commandPath = `.claude/commands/${commandName}.md`;

return [{
  json: {
    command_name: commandName,
    command_path: commandPath,
    pattern,
    occurrence_count: pattern.occurrence_count || 0,
    requested_at: new Date().toISOString(),
  },
}];

