// Validate generated command markdown
const response = $input.first().json;
const content = response.content?.[0]?.text;

if (!content) {
  throw new Error('No content from Anthropic response');
}

let cleanContent = content
  .replace(/^```(?:markdown|md)?\n?/m, '')
  .replace(/\n?```\s*$/m, '')
  .trim();

if (!cleanContent.endsWith('\n')) cleanContent += '\n';

const hasFrontmatter = /^---\n[\s\S]*?\nname:\s*\S+/m.test(cleanContent);
const hasDescription = /^description:\s*.{50,}/m.test(cleanContent);
const hasSections = (cleanContent.match(/^##\s+/gm) || []).length;

const validation = {
  has_frontmatter: hasFrontmatter,
  has_description: hasDescription,
  section_count: hasSections,
  passed: hasFrontmatter && hasDescription && hasSections >= 2,
};

return [{
  json: {
    ...$('Validate + Derive Identity').item.json,
    rendered_content: cleanContent,
    validation,
  },
}];

